import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // ---- Texted Plane ----
  const planeGeom = new ctx.THREE.PlaneGeometry(1, 0.3);
  const planeMat = new MeshBasicNodeMaterial({ transparent: false });
  const planeMesh = new ctx.THREE.Mesh(planeGeom, planeMat);
  group.add(planeMesh);

  // Load texture asynchronously; assign when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ---- Text Content ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.visualSpec?.colors?.paper ?? '#e8ecf2'),
      align: 'center',
      maxWidthPx: 512,
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  }

  // ---- Event Handlers Placeholder ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    // Dispose material & geometry
    planeMat.dispose();
    planeGeom.dispose();
    // Dispose any textures created by the loader (if needed)
    if (planeMat.map && planeMat.map.dispose) {
      planeMat.map.dispose();
    }
    // Kill any GSAP timelines (none created here)
    gsap.globalTimeline.clear();
  };

  return group;
}
